mapper.select:
select
con.Con_Name as conName, sec.Sec_Name as secName, c1.C_Name_History as glsWarranteeNameHistory, c3.C_Name_History as glbCompanyNameHistory, c1.C_Name as glsWarranteeName, c3.C_Name as glbCompanyName, c1.C_Abbreviation as glsWarranteeAbbName, c3.C_Abbreviation as glbCompanyAbbName, gls.Gls_Code as glsCode, gls.Gls_Type as glsType, f.file_relation_id as fileRelationId, mn.* from Guarantee_Letter_Back mn left join Guarantee_Letter_Sign gls on gls.Gls_Id=mn.Gls_Id left join Pre_Project pro on pro.P_Id=gls.P_Id
left join Sec_Info sec on sec.Sec_Id=gls.Sec_Id left join Con_Contract con on con.Con_Id=gls.Con_Id left join SYS_Company c1 on gls.Gls_Warrantee=c1.C_Id left join SYS_Company c3 on mn.Glb_Company_Id=c3.C_Id left join Sys_File f on f.FileID=mn.Glb_Id where 1=1
and mn.Te_Id = #{params.teId}
and gls.P_Id=#{params.pId}
and mn.Glb_Completion=#{params.glbCompletion}
and c3.C_Name like concat('%',#{params.glbCompanyName},'%')
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and sec.Sec_Name like concat('%',#{params.secName},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Glb_Create_Time desc
